"""Prepare reusable Linux runtime assets on a CPU Kaggle worker; no model load."""
from pathlib import Path
import hashlib
import importlib.metadata as md
import json
import os
import platform
import re
import shutil
import subprocess
import sys
import tarfile
import time
import traceback

OUT = Path('/kaggle/working/vfarl-cpu-stage')
OUT.mkdir(parents=True, exist_ok=True)
START = time.monotonic()
REPORT = {'purpose': 'Linux dependency and isolation preparation; zero GPU/model execution',
          'python': sys.version, 'platform': platform.platform(), 'phases': [],
          'task_environments': []}


def digest(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()


def record(phase, **values):
    REPORT.update(values)
    REPORT['phases'].append({'phase': phase, 'elapsed_seconds': time.monotonic() - START})
    (OUT / 'preparation.json').write_text(json.dumps(REPORT, indent=2) + '\n')
    print(json.dumps({'phase': phase, **values}), flush=True)


def run(command, *, env=None, log=None, check=True):
    result = subprocess.run(command, env=env, text=True, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT)
    if log:
        Path(log).write_text(result.stdout)
    print(result.stdout[-6000:], flush=True)
    if check and result.returncode:
        raise RuntimeError(f'Command failed ({result.returncode}): {command!r}')
    return result


def main():
    import torch
    if torch.cuda.is_available() or torch.cuda.device_count():
        raise RuntimeError('CPU preparation refuses an attached GPU')
    if sys.version_info[:2] != (3, 12):
        raise RuntimeError('Use the pinned Linux Python 3.12 Kaggle image')
    record('runtime', torch=torch.__version__, cuda_available=False)
    # CPU-only capability evidence. Full state isolation is never inferred from OS name.
    bwrap = shutil.which('bwrap')
    if not bwrap and shutil.which('apt-get'):
        run(['apt-get', 'update'], check=False, log=OUT / 'apt-update.log')
        run(['apt-get', 'install', '-y', 'bubblewrap'], check=False, log=OUT / 'apt-bwrap.log')
        bwrap = shutil.which('bwrap')
    command = ([bwrap, '--unshare-user', '--unshare-pid', '--unshare-net', '--die-with-parent',
                '--ro-bind', '/', '/', '--proc', '/proc', '--dev', '/dev',
                '--tmpfs', '/tmp', '--', '/bin/sh', '-c', 'printf vfarl-isolated'] if bwrap else [])
    isolation = run(command, check=False, log=OUT / 'bwrap.log') if command else None
    if bwrap:
        (OUT / 'bin').mkdir(exist_ok=True)
        shutil.copy2(bwrap, OUT / 'bin/bwrap')
    record('isolation', isolation={'command': command,
           'returncode': isolation.returncode if isolation else None,
           'available': bool(isolation and isolation.returncode == 0),
           'state_claim': 'namespace_isolation_available' if isolation and isolation.returncode == 0
                          else 'observable_replay_only'})

    caches = []
    for manifest in Path('/kaggle/input').rglob('cache-manifest.json'):
        value = json.loads(manifest.read_text())
        if value.get('source') == 'google/gemma-4/Transformers/gemma-4-31b-it-qat-q4_0-unquantized/2':
            caches.append({'path': str(manifest.parent), 'manifest_sha256': digest(manifest),
                           'source': value['source']})
    if len(caches) != 1:
        raise RuntimeError(f'Expected one existing official NF4 cache: {caches}')
    record('cache_inventory', nf4_cache=caches[0], cache_copied=False, weights_loaded=False)
    roots = [p.parent for p in Path('/kaggle/input').rglob('tokenizer.json')
             if 'gemma-4-31b-it-qat-w4a16-ct' in str(p)]
    if len(roots) != 1:
        raise RuntimeError(f'Expected one official CT v2 tokenizer mount: {roots}')
    tokenizer = OUT / 'tokenizer'
    tokenizer.mkdir(exist_ok=True)
    for name in ('tokenizer.json', 'tokenizer_config.json', 'chat_template.jinja',
                 'config.json', 'generation_config.json'):
        shutil.copy2(roots[0] / name, tokenizer / name)
    record('tokenizer', tokenizer={'source': 'google/gemma-4/Other/gemma-4-31b-it-qat-w4a16-ct/2',
           'files': {p.name: {'bytes': p.stat().st_size, 'sha256': digest(p)}
                     for p in tokenizer.iterdir()}})

    wheelhouse = [p for p in Path('/kaggle/input').rglob('adk_submission-*.whl')]
    if len(wheelhouse) != 1:
        raise RuntimeError(f'Expected one official wheelhouse: {wheelhouse}')
    wheelhouse = wheelhouse[0].parent
    core_wheels = []
    for pattern in ('adk_submission-*.whl', 'adk_eval_core-*.whl', 'swegemma-*.whl'):
        found = list(wheelhouse.glob(pattern))
        if len(found) != 1:
            raise RuntimeError(f'Missing/ambiguous official wheel {pattern}')
        core_wheels.append(found[0])
    requested = ['transformers==5.13.1', 'peft==0.21.2', 'accelerate==1.15.0',
                 'safetensors==0.8.0', 'tokenizers==0.22.2', 'PyYAML==6.0.3',
                 'bitsandbytes==0.50.2', 'uv', *map(str, core_wheels)]
    resolution = OUT / 'runtime-resolution.json'
    constraint = OUT / 'stock-torch.txt'
    constraint.write_text('torch==' + torch.__version__ + '\n')
    run([sys.executable, '-m', 'pip', 'install', '--dry-run', '--report', str(resolution),
         '--find-links', str(wheelhouse), '-c', str(constraint), *requested],
        log=OUT / 'runtime-resolution.log')
    proposals = json.loads(resolution.read_text())['install']
    forbidden = [x['metadata']['name'] for x in proposals
                 if x['metadata']['name'].lower().replace('_', '-').startswith(('torch', 'nvidia-', 'triton'))]
    if forbidden:
        raise RuntimeError('Refuse replacing image CUDA packages: ' + repr(forbidden))
    wheels = OUT / 'runtime-wheels'
    wheels.mkdir(exist_ok=True)
    pins = {x['metadata']['name']: x['metadata']['name'] + '==' + x['metadata']['version']
            for x in proposals}
    pins.update({p.split('==')[0]: p for p in requested if '==' in p})
    pins.pop('swegemma', None)
    pins.pop('adk-eval-core', None)
    pins.pop('adk-submission', None)
    run([sys.executable, '-m', 'pip', 'download', '--no-deps', '--only-binary=:all:',
         '--find-links', str(wheelhouse), '-d', str(wheels), *pins.values()],
        log=OUT / 'runtime-download.log')
    for p in core_wheels:
        shutil.copy2(p, wheels / p.name)
    deps = OUT / 'runtime'
    run([sys.executable, '-m', 'pip', 'install', '--no-index', '--no-deps', '--target', str(deps),
         *map(str, sorted(wheels.glob('*.whl')))], log=OUT / 'runtime-install.log')
    env = dict(os.environ, PYTHONPATH=str(deps))
    run([sys.executable, '-c', 'import torch,transformers,peft,bitsandbytes,swegemma,adk_submission,adk_eval_core; '
         'from transformers import AutoTokenizer; import sys; '
         't=AutoTokenizer.from_pretrained(sys.argv[1],local_files_only=True); '
         'print({"imports_ok":True,"tokenizer_size":len(t),"torch":torch.__version__})', str(tokenizer)],
        env=env, log=OUT / 'runtime-import.log')
    record('runtime_ready', runtime_wheels=[{'name': p.name, 'bytes': p.stat().st_size, 'sha256': digest(p)}
                                           for p in sorted(wheels.glob('*.whl'))])
    uv = deps / 'bin/uv'
    if not uv.is_file():
        raise RuntimeError('uv executable missing from staged runtime')
    python_root = OUT / 'python'
    env = dict(env, UV_PYTHON_INSTALL_DIR=str(python_root))
    profiles = ENVIRONMENT_PROFILES['profiles']
    for index, profile in enumerate(profiles):
        key = f'profile-{index:02d}'
        dest = OUT / 'task-envs' / key
        dest.parent.mkdir(exist_ok=True)
        match = re.search(r'/python(3\.\d+)/', profile['source_profile'])
        version = profile.get('python_version_pin') or (match.group(1) if match else '3.12')
        result = {'id': key, 'source_profile': profile['source_profile'],
                  'tasks': profile['tasks'], 'python_requested': version,
                  'python_abi': '.'.join(version.split('.')[:2]), 'success': False,
                  'excluded_host_packages': {'pipdeptree': 'Unpublished local development version; no task dependency.'} if 'pipdeptree' in (profile.get('packages') or {}) else {}}
        try:
            run([str(uv), 'python', 'install', version], env=env, log=OUT / f'{key}-python.log')
            run([str(uv), 'venv', '--python', version, str(dest)], env=env,
                log=OUT / f'{key}-venv.log')
            packages = profile.get('packages') or {}
            pins = [f'{name}=={version}' for name, version in packages.items()
                    if name.lower().replace('_', '-') not in ('pip', 'pipdeptree', 'swegemma', 'adk-submission', 'adk-eval-core')]
            if not pins:
                pins = ['pytest==8.3.3']
            run([str(uv), 'pip', 'install', '--python', str(dest / 'bin/python'),
                 '--find-links', str(wheelhouse), *pins], env=env, log=OUT / f'{key}-install.log')
            inventory = run([str(uv), 'pip', 'freeze', '--python', str(dest / 'bin/python')],
                            env=env, log=OUT / f'{key}-freeze.txt')
            result.update(success=True, environment_path=str(dest), actual_packages=inventory.stdout.splitlines())
        except Exception as exc:
            result['error'] = str(exc)
        REPORT['task_environments'].append(result)
        record('task_environment', last_task_environment=result)
    record('complete', success=all(p['success'] for p in REPORT['task_environments']))


if __name__ == '__main__':
    try:
        main()
    except BaseException:
        (OUT / 'exception.txt').write_text(traceback.format_exc())
        record('failed', success=False, error=traceback.format_exc())
        raise
    finally:
        # Opaque extension avoids Kaggle recursively unpacking venv/source archives.
        record('archive_start')
        with tarfile.open('/kaggle/working/vfarl-cpu-stage.bin', 'w:gz', compresslevel=1) as archive:
            archive.add(OUT, arcname=OUT.name)
        print(json.dumps({'phase': 'archive_completed', 'bytes': Path('/kaggle/working/vfarl-cpu-stage.bin').stat().st_size}), flush=True)
        shutil.copy2(OUT / 'preparation.json', '/kaggle/working/vfarl-preparation.json')
        shutil.rmtree(OUT)

_extension_source = '"""Extend the accepted Linux runtime with Unsloth dependencies on a CPU worker.\n\nThis prepares an offline GPU runtime. It never imports Unsloth, loads a model,\nor claims that CUDA kernels or the VFARL integration have been exercised.\n"""\nfrom pathlib import Path\nimport argparse\nimport copy\nimport hashlib\nimport importlib\nimport importlib.metadata as metadata\nimport json\nimport os\nimport platform\nimport re\nimport shutil\nimport subprocess\nimport sys\nimport tarfile\nimport time\nimport traceback\nimport urllib.parse\nimport urllib.request\n\n\nWORK = Path(\'/kaggle/working\')\nSTAGE = WORK / \'vfarl-cpu-stage\'\nEVIDENCE = WORK / \'vfarl-unsloth-preparation\'\nBASE_RUNTIME_SHA256 = \'9475d9a2617135c276d3b4ad87884b28425f871e806c07b62bfc62d4af0cce7e\'\nEXPECTED = {\'transformers\': \'5.13.1\', \'peft\': \'0.21.2\',\n            \'bitsandbytes\': \'0.50.2\', \'accelerate\': \'1.15.0\',\n            \'tokenizers\': \'0.22.2\'}\nUNSLOTH_PINS = {\'unsloth\': \'2026.10.9\', \'unsloth-zoo\': \'2026.10.9\'}\n# The stock torchao 0.10.0 conflicts with the measured Unsloth Zoo dependency\n# >=0.13.0. It may be shadowed in this overlay; CUDA and the model stack stay put.\nOVERLAY_REPLACEMENTS = {\'torchao\'}\nSTARTED = time.monotonic()\nREPORT = {\'purpose\': \'CPU-only dependency resolution and offline runtime assembly\',\n          \'gpu_model_loaded\': False, \'unsloth_import_attempted\': False,\n          \'base_runtime_sha256\': BASE_RUNTIME_SHA256, \'phases\': []}\n\n\ndef digest(path):\n    h = hashlib.sha256()\n    with Path(path).open(\'rb\') as stream:\n        for block in iter(lambda: stream.read(1024 * 1024), b\'\'):\n            h.update(block)\n    return h.hexdigest()\n\n\ndef canonical(name):\n    return re.sub(r\'[-_.]+\', \'-\', name).lower()\n\n\ndef write(path, data):\n    Path(path).write_text(json.dumps(data, ensure_ascii=False, indent=2) + \'\\n\')\n\n\ndef record(phase, **fields):\n    REPORT.update(fields)\n    REPORT[\'phases\'].append({\'phase\': phase, \'seconds\': time.monotonic() - STARTED})\n    write(EVIDENCE / \'preparation.json\', REPORT)\n    print(json.dumps({\'phase\': phase, **fields}), flush=True)\n\n\ndef unpack(path, root):\n    # Keep the same symlink and path semantics as the accepted GPU carrier.\n    root = root.resolve()\n    def safe_filter(member, destination):\n        if member.issym() and os.path.isabs(member.linkname):\n            target = Path(member.linkname).resolve()\n            if not target.is_relative_to(root):\n                raise RuntimeError(\'Archive symlink escapes extraction root\')\n            member = copy.copy(member)\n            member.linkname = os.path.relpath(target, (root / member.name).parent)\n        return tarfile.data_filter(member, destination)\n    with tarfile.open(path) as archive:\n        for member in archive.getmembers():\n            if not (root / member.name).resolve().is_relative_to(root):\n                raise RuntimeError(\'Archive path escape\')\n        archive.extractall(root, filter=safe_filter)\n\n\ndef installed_versions():\n    versions = {}\n    for distribution in metadata.distributions():\n        name = canonical(distribution.metadata[\'Name\'])\n        versions.setdefault(name, distribution.version)\n    return versions\n\n\ndef command(arguments, env, log):\n    result = subprocess.run(arguments, env=env, text=True,\n                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT)\n    log.write_text(result.stdout)\n    print(result.stdout[-12000:], flush=True)\n    if result.returncode:\n        raise RuntimeError(\'Dependency preparation failed (%d); see %s\' %\n                           (result.returncode, log.name))\n\n\ndef main(base_runtime_sha256=None):\n    expected_base = base_runtime_sha256 or BASE_RUNTIME_SHA256\n    if not re.fullmatch(r\'[0-9a-f]{64}\', expected_base):\n        raise ValueError(\'Expected an explicit lowercase SHA256 for the base runtime\')\n    REPORT[\'base_runtime_sha256\'] = expected_base\n    EVIDENCE.mkdir(parents=True, exist_ok=False)\n    import torch\n    if torch.cuda.is_available() or torch.cuda.device_count():\n        raise RuntimeError(\'CPU preparation refuses any attached CUDA device\')\n    if sys.version_info[:2] != (3, 12) or torch.__version__ != \'2.10.0+cu128\':\n        raise RuntimeError(\'Pinned Python3.12 / torch2.10.0+cu128 image required\')\n    if STAGE.exists():\n        raise RuntimeError(\'Fresh CPU stage path required\')\n    record(\'cpu_environment\', python=sys.version, platform=platform.platform(),\n           stock_torch=torch.__version__, stock_triton=metadata.version(\'triton\'))\n    archives = [WORK / \'vfarl-cpu-stage.bin\']\n    if len(archives) != 1 or digest(archives[0]) != expected_base:\n        raise RuntimeError(\'Missing or changed accepted base runtime archive\')\n    unpack(archives[0], WORK)\n    runtime = STAGE / \'runtime\'\n    sys.path.insert(0, str(runtime))\n    importlib.invalidate_caches()\n    environment = dict(os.environ, PYTHONPATH=str(runtime),\n                       PIP_DISABLE_PIP_VERSION_CHECK=\'1\')\n    base_preparation = STAGE / \'preparation.json\'\n    base_preparation_sha = digest(base_preparation)\n    initial = installed_versions()\n    if initial.get(\'torch\') != REPORT[\'stock_torch\'] or initial.get(\'triton\') != REPORT[\'stock_triton\']:\n        raise RuntimeError(\'Accepted overlay must reuse the pinned stock torch/triton\')\n    for name, expected in EXPECTED.items():\n        if initial.get(name) != expected:\n            raise RuntimeError(\'Accepted runtime version differs: %s=%r, expected %s\' %\n                               (name, initial.get(name), expected))\n    # Preserve the accepted runtime, with only the observed torchao dependency\n    # repair allowed as a new overlay package. Task venvs are never changed.\n    constraints = EVIDENCE / \'existing-constraints.txt\'\n    preserved = {name: version for name, version in initial.items()\n                 if name not in OVERLAY_REPLACEMENTS}\n    constraints.write_text(\'\'.join(\'%s==%s\\n\' % item for item in sorted(preserved.items())))\n    record(\'base_runtime_ready\', base_archive_bytes=archives[0].stat().st_size,\n           base_preparation_sha256=base_preparation_sha,\n           base_packages=initial, preserved_packages=preserved,\n           allowed_overlay_replacements={name: initial.get(name) for name in sorted(OVERLAY_REPLACEMENTS)},\n           unsloth_pins=UNSLOTH_PINS, constraints_sha256=digest(constraints))\n    tokenizer = STAGE / \'tokenizer\'\n    original_tokenizer = {p.name: digest(p) for p in tokenizer.iterdir() if p.is_file()}\n    roots = [p.parent for p in Path(\'/kaggle/input\').rglob(\'tokenizer.json\')\n             if \'gemma-4-31b-it-qat-w4a16-ct\' in str(p)]\n    if len(roots) != 1:\n        raise RuntimeError(\'Expected exactly one official CTv2 processor mount\')\n    added = []\n    for path in sorted(roots[0].glob(\'*processor*.json\')):\n        target = tokenizer / path.name\n        if not target.exists():\n            shutil.copy2(path, target)\n            added.append({\'name\': path.name, \'bytes\': target.stat().st_size,\n                          \'sha256\': digest(target)})\n    if not any(\'processor\' in p.name for p in tokenizer.glob(\'*.json\')):\n        raise RuntimeError(\'Official processor/preprocessor assets are absent\')\n    if any(digest(tokenizer / name) != value for name, value in original_tokenizer.items()):\n        raise RuntimeError(\'Existing tokenizer/template/config changed\')\n    record(\'processor_assets\', official_source=\'google/gemma-4/Other/gemma-4-31b-it-qat-w4a16-ct/2\',\n           existing_tokenizer_files=original_tokenizer, added_processor_files=added)\n    resolver_report = EVIDENCE / \'pip-resolver-report.json\'\n    command([sys.executable, \'-m\', \'pip\', \'install\', \'--dry-run\', \'--report\',\n             str(resolver_report), \'--constraint\', str(constraints),\n             *[name + \'==\' + version for name, version in UNSLOTH_PINS.items()]],\n            environment, EVIDENCE / \'pip-resolver.log\')\n    resolved = json.loads(resolver_report.read_text())\n    proposals = resolved.get(\'install\', [])\n    forbidden = []\n    for proposal in proposals:\n        name = canonical(proposal[\'metadata\'][\'name\'])\n        if ((name in initial and name not in OVERLAY_REPLACEMENTS)\n                or name in (\'torch\', \'triton\', \'pytorch-triton\') or name.startswith(\'nvidia-\')):\n            forbidden.append({\'name\': name, \'version\': proposal[\'metadata\'][\'version\']})\n    if forbidden:\n        record(\'dependency_conflict\', forbidden_replacements=forbidden)\n        raise RuntimeError(\'Resolver proposed replacing the frozen runtime or CUDA stack\')\n    selected = {canonical(p[\'metadata\'][\'name\']): p[\'metadata\'][\'version\'] for p in proposals}\n    if not all(name in selected or name in initial for name in (\'unsloth\', \'unsloth-zoo\')):\n        raise RuntimeError(\'Resolver did not supply both Unsloth packages\')\n    replacements = {name: {\'previous_version\': initial[name], \'overlay_version\': version}\n                    for name, version in selected.items() if name in initial}\n    record(\'dependencies_resolved\', newly_selected=selected, overlay_replacements=replacements,\n           resolver_report_sha256=digest(resolver_report))\n    wheelhouse = WORK / \'vfarl-unsloth-wheels\'\n    wheelhouse.mkdir(exist_ok=False)\n    wheels = []\n    for proposal in proposals:\n        info = proposal[\'download_info\']\n        url = info[\'url\']\n        name = Path(urllib.parse.unquote(urllib.parse.urlparse(url).path)).name\n        if not name.endswith(\'.whl\'):\n            raise RuntimeError(\'Only resolved wheels may be installed: \' + name)\n        path = wheelhouse / name\n        urllib.request.urlretrieve(url, path)\n        actual = digest(path)\n        expected = info.get(\'archive_info\', {}).get(\'hashes\', {}).get(\'sha256\')\n        if not expected or actual != expected:\n            raise RuntimeError(\'Resolved wheel hash mismatch: \' + name)\n        wheels.append({\'package\': canonical(proposal[\'metadata\'][\'name\']),\n                       \'version\': proposal[\'metadata\'][\'version\'], \'wheel\': name,\n                       \'bytes\': path.stat().st_size, \'sha256\': actual, \'url\': url})\n        upgrade = [\'--upgrade\'] if canonical(proposal[\'metadata\'][\'name\']) in replacements else []\n        command([sys.executable, \'-m\', \'pip\', \'install\', \'--no-deps\', \'--no-compile\',\n                 *upgrade, \'--target\', str(runtime), str(path)], environment,\n                EVIDENCE / (\'install-%s.log\' % canonical(proposal[\'metadata\'][\'name\'])))\n    subprocess_code = (\n        \'import importlib.metadata as m,json,torch,transformers,peft,bitsandbytes,accelerate,trl; \'\n        \'names=("torch","triton","transformers","peft","bitsandbytes","accelerate",\'\n        \'"tokenizers","trl","unsloth","unsloth_zoo"); \'\n        \'print(json.dumps({"versions":{n:m.version(n) for n in names},\'\n        \'"cuda_available":torch.cuda.is_available(),\'\n        \'"unsloth_import_attempted":False}))\')\n    command([sys.executable, \'-c\', subprocess_code], environment,\n            EVIDENCE / \'cpu-module-imports.log\')\n    # Read metadata only; importing Unsloth on CPU would incorrectly require GPU.\n    expected_final = dict(EXPECTED, torch=initial[\'torch\'], triton=initial[\'triton\'], **UNSLOTH_PINS)\n    expected_final.update({name: value[\'overlay_version\'] for name, value in replacements.items()})\n    final_output = subprocess.run([sys.executable, \'-c\',\n        \'import importlib.metadata as m,json;print(json.dumps({n:m.version(n) for n in \'+repr(list(expected_final))+ \'}))\'],\n        env=environment, text=True, capture_output=True, check=True)\n    final_versions = json.loads(final_output.stdout)\n    for name, expected in expected_final.items():\n        if final_versions.get(name) != expected:\n            raise RuntimeError(\'Runtime package differs from resolved assembly: \' + name)\n    extension = {\'base_runtime_sha256\': expected_base,\n                 \'base_preparation_sha256\': base_preparation_sha,\n                 \'new_packages\': wheels, \'original_tokenizer_files\': original_tokenizer,\n                 \'overlay_replacements\': replacements, \'final_versions\': final_versions,\n                 \'added_processor_files\': added, \'gpu_verified\': False,\n                 \'unsloth_import_attempted\': False,\n                 \'limitation\': \'Only CPU dependency assembly and ordinary module imports ran. CUDA, model load, kernels, FSDP and VFARL remain unmeasured.\'}\n    old = json.loads(base_preparation.read_text())\n    old[\'unsloth_extension\'] = extension\n    write(base_preparation, old)\n    write(EVIDENCE / \'unsloth-extension.json\', extension)\n    record(\'runtime_assembled\', new_packages=wheels, task_environments_reused=True,\n           gpu_verified=False, ordinary_cpu_imports_completed=True)\n    shutil.rmtree(wheelhouse)\n    target = WORK / \'vfarl-cpu-stage.bin\'\n    with tarfile.open(target, \'w:gz\', compresslevel=1) as archive:\n        archive.add(STAGE, arcname=STAGE.name)\n    archive_record = {\'path\': target.name, \'bytes\': target.stat().st_size,\n                      \'sha256\': digest(target), \'base_runtime_sha256\': expected_base,\n                      \'gpu_verified\': False, \'new_packages\': selected,\n                      \'overlay_replacements\': replacements,\n                      \'wall_seconds\': time.monotonic() - STARTED}\n    write(WORK / \'runtime-archive.json\', archive_record)\n    record(\'archive_completed\', **archive_record, success=True)\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--base-runtime-sha256\', default=BASE_RUNTIME_SHA256,\n                        help=\'Actual SHA256 of the mounted accepted CPU archive; historical default retained\')\n    args = parser.parse_args()\n    if not re.fullmatch(r\'[0-9a-f]{64}\', args.base_runtime_sha256):\n        parser.error(\'--base-runtime-sha256 must be a lowercase SHA256\')\n    try:\n        main(args.base_runtime_sha256)\n    except BaseException:\n        EVIDENCE.mkdir(exist_ok=True)\n        (EVIDENCE / \'exception.txt\').write_text(traceback.format_exc())\n        record(\'failed\', success=False, error=traceback.format_exc())\n        raise\n    finally:\n        if STAGE.exists():\n            shutil.rmtree(STAGE)\n        wheels = WORK / \'vfarl-unsloth-wheels\'\n        if wheels.exists():\n            shutil.rmtree(wheels)\n'

_fresh_archive = Path('/kaggle/working/vfarl-cpu-stage.bin')
_fresh_sha = digest(_fresh_archive)
_base_record = {'sha256': _fresh_sha, 'bytes': _fresh_archive.stat().st_size,
                'base_runtime_prepared': bool(REPORT.get('success')),
                'successful_task_environments': sum(bool(row.get('success')) for row in REPORT['task_environments'])}
Path('/kaggle/working/base-runtime-archive.json').write_text(json.dumps(_base_record, indent=2)+'\n')
_extension_namespace = {'__name__': 'vfarl_fresh_unsloth_extension'}
exec(compile(_extension_source, 'prepare_unsloth_runtime.py', 'exec'), _extension_namespace)
_extension_completed = False
try:
    _extension_namespace['main'](_fresh_sha)
    _extension_completed = True
except BaseException:
    _evidence = _extension_namespace['EVIDENCE']
    _evidence.mkdir(exist_ok=True)
    _failure = traceback.format_exc()
    (_evidence / 'exception.txt').write_text(_failure)
    print(json.dumps({'phase': 'unsloth_extension_failed', 'error': _failure,
                      'base_runtime_preserved': _fresh_archive.exists() and digest(_fresh_archive)==_fresh_sha}), flush=True)
    if not _fresh_archive.exists() or digest(_fresh_archive)!=_fresh_sha:
        raise
finally:
    _stage = _extension_namespace['STAGE']
    if _stage.exists(): shutil.rmtree(_stage)
    _wheels = Path('/kaggle/working/vfarl-unsloth-wheels')
    if _wheels.exists(): shutil.rmtree(_wheels)
_outcome = {'base_runtime_prepared': _base_record['base_runtime_prepared'],
            'unsloth_extension_completed': _extension_completed,
            'actual_archive_sha256': digest(_fresh_archive),
            'actual_archive_bytes': _fresh_archive.stat().st_size,
            'gpu_model_loaded': False}
Path('/kaggle/working/runtime-preparation-outcome.json').write_text(json.dumps(_outcome,indent=2)+'\n')
print(json.dumps({'phase': 'cpu_preparation_finished', **_outcome}), flush=True)
